// Combine the detection from Python with RDAP and DNS enrichment,
// decide whether it deserves an alert, and build the Telegram message.
// Returning an empty array stops the workflow (no alert sent).

const d = $('Webhook').first().json.body;
const rdap = $('RDAP lookup').first().json || {};
const dns = $('DNS lookup').first().json || {};

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// --- Domain age from RDAP -------------------------------------------------
let registeredAt = null;
let ageDays = null;
const reg = (rdap.events || []).find(e => e.eventAction === 'registration');
if (reg && reg.eventDate) {
  registeredAt = reg.eventDate.slice(0, 10);
  ageDays = Math.floor((Date.now() - new Date(reg.eventDate)) / 86400000);
}

// Registrar name (RDAP entity with the "registrar" role)
let registrar = null;
const regEntity = (rdap.entities || []).find(e => (e.roles || []).includes('registrar'));
if (regEntity && regEntity.vcardArray && regEntity.vcardArray[1]) {
  const fn = regEntity.vcardArray[1].find(f => f[0] === 'fn');
  if (fn) registrar = fn[3];
}

// --- IPs from DNS over HTTPS ----------------------------------------------
const ips = (dns.Answer || []).filter(a => a.type === 1).map(a => a.data);

// --- Alert decision -------------------------------------------------------
// Alert if the Python score already crossed the alert threshold, OR if a
// lower-scoring domain was registered in the last 7 days and already resolves.
const highScore = d.score >= d.alert_threshold;
const freshAndLive = ageDays !== null && ageDays <= 7 && ips.length > 0;

if (!highScore && !freshAndLive) {
  return [];
}

const escalation = !highScore && freshAndLive
  ? '\n⚠️ <b>Escalated:</b> below alert score, but registered recently and already live.'
  : '';

const reasons = (d.reasons || []).map(r => `• ${esc(r)}`).join('\n');
const text =
`🚨 <b>Possible ${esc(d.brand)} phishing domain</b>

<b>Domain:</b> <code>${esc(d.domain_defanged)}</code>
<b>Score:</b> ${d.score}
<b>Source:</b> ${esc(d.source)}

<b>Why:</b>
${reasons}

<b>Enrichment:</b>
• Registered: ${registeredAt ? `${registeredAt} (${ageDays} days ago)` : 'unknown'}
• Registrar: ${esc(registrar || 'unknown')}
• Resolves to: ${ips.length ? esc(ips.join(', ').replace(/\./g, '[.]')) : 'no A record'}${escalation}`;

return [{ json: { text, domain: d.domain, brand: d.brand, score: d.score, ageDays, ips } }];
